-- reporte-uso-escenarios: Horas de uso por docente, materia y escenario en un rango (agrupación con join lateral).
-- Origen: app/Services/ReporteService.php:57 usoDeEscenarios
-- SQL capturado de Laravel con rendimiento/base-de-datos/capturar-consultas.php; no se edita a mano.
\set off random(-440, -30)

select "users"."nombre" as "docente_nombre", "materias"."nombre" as "materia_nombre", "materias"."semestre" as "materia_semestre", "casos_clinicos"."nombre" as "caso_clinico_nombre", COALESCE(salas_de_la_sesion.nombres, 'Sin asignar') as sala_nombre, "solicitudes"."tipo", COUNT(solicitudes.id) as sesiones, SUM(EXTRACT(EPOCH FROM (solicitudes.hora_fin - solicitudes.hora_inicio)) / 3600) as horas, SUM(solicitudes.cantidad_estudiantes) as total_estudiantes, COUNT(solicitudes.docente_que_dicta_id) as sesiones_por_sustitucion from "solicitudes" left join "preparaciones" on "preparaciones"."solicitud_id" = "solicitudes"."id" left join lateral (select string_agg(salas.nombre, ' + ' ORDER BY salas.nombre) as nombres from "preparacion_sala" inner join "salas" on "salas"."id" = "preparacion_sala"."sala_id" where "preparacion_sala"."preparacion_id" = "preparaciones"."id") as "salas_de_la_sesion" on true inner join "users" on "users"."id" = COALESCE(solicitudes.docente_que_dicta_id, solicitudes.docente_id) inner join "materias" on "materias"."id" = "solicitudes"."materia_id" inner join "casos_clinicos" on "casos_clinicos"."id" = "solicitudes"."caso_clinico_id" where "solicitudes"."estado" = 'aprobada' and "solicitudes"."fecha"::date >= (CURRENT_DATE + :off) and "solicitudes"."fecha"::date <= (CURRENT_DATE + :off + 60) group by "users"."id", "materias"."id", "casos_clinicos"."id", "salas_de_la_sesion"."nombres", "solicitudes"."tipo" order by "users"."nombre" asc, "materias"."nombre" asc, "casos_clinicos"."nombre" asc;
